sys_script_fix.script:
var issues = new GlideRecord('sn_grc_issue');
issues.addNotNullQuery('issue_type');
issues.query();
var issueType;
while (issues.next()) {
    switch (issues.getValue('issue_type')) {
        case 'control_failure':
            issueType = '11';
            break;
        case 'policy_violation':
            issueType = '3';
            break;
        case 'data_breach':
            issueType = '13';
            break;
        case 'process_violation':
            issueType = '6';
            break;
        case 'documentation':
            issueType = '14';
            break;
        case 'fraud':
            issueType = '15';
            break;
        case 'misstatement':
            issueType = '16';
            break;
        case 'training':
            issueType = '17';
            break;
        case 'other':
            issueType = '10';
            break;
    }
    issues.setValue('issue_type', issueType);
	issues.setWorkflow(false);
    issues.update();
}
